record.field:
if records:
    config = env["stockpilot.configuration"].get_config()
    if not config:
        raise UserError("No Stockpilot configuration found")
    batch_export_name = "Batch Export - %s" % str(len(records))
    job_batch = env["queue.job.batch"].get_new_batch(batch_export_name)
    batch_export = env["stockpilot.batch.export"].create({
        "name": batch_export_name,
        "config_id": config.id,
        "job_batch_id": job_batch.id,
    })
    for rec in records:
        rec.write({"exported_to_stockpilot": True})
        batch_export.with_context(job_batch=job_batch).with_delay()._export_single_product(rec.id)
    job_batch.enqueue()
